<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { application } from '../../js/app.js';

const props=defineProps({
  type:{type:String,required:true},
  mode:{type:String,default:'CREATE'},
  record:{type:Object,default:null},
  authoritativeOdometer:{type:[Number,String],default:null}
});
const emit=defineEmits(['close','saved']);

const busy=ref(false),error=ref(''),success=ref(''),gpsStatus=ref('Waiting for GPS…');
const draft=ref({});
let watchId=null;
let lastPosition=null;
let reverseTimer=null;

const authoritative=computed(()=>props.authoritativeOdometer==null||props.authoritativeOdometer===''?null:Number(props.authoritativeOdometer));
const isFuel=computed(()=>props.type==='FUEL');
const title=computed(()=>isFuel.value?'Fuel':props.type.replaceAll('_',' '));
const quantityKg=computed(()=>{if(!isFuel.value)return null;const amount=Number(draft.value.amount),price=Number(draft.value.pricePerKg);return Number.isFinite(amount)&&amount>0&&Number.isFinite(price)&&price>0?amount/price:null;});
const timestampLabel=computed(()=>{const value=draft.value.recordedAt||draft.value.startedAt||new Date().toISOString();const d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleString(): 'Time unavailable';});
const locationLabel=computed(()=>draft.value.locationName||'Location unavailable');

function localDate(value){const d=value?new Date(value):new Date();return Number.isFinite(d.getTime())?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';}
function toLocalInput(value){if(!value)return '';const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;}
function fromLocalInput(value){return value?new Date(value).toISOString():null;}
function setDraftFromRecord(){const r=props.record||{};if(props.type==='FUEL'){draft.value={recordedAt:toLocalInput(r.occurredAt||r.recorded_at||r.date)||toLocalInput(new Date()),odometer:r.odometer??authoritative.value??'',pricePerKg:r.pricePerKg??r.price_per_kg??'',amount:r.amount??(r.amount_paise!=null?Number(r.amount_paise)/100:''),locationName:r.locationName??r.location_name??'',locationArea:r.locationArea??r.location_area??null};return;}if(props.type==='WORK_SESSION'){draft.value={startedAt:toLocalInput(r.occurredAt||r.started_at),endedAt:toLocalInput(r.ended_at),startOdometer:r.start_odometer??'',endOdometer:r.end_odometer??'',breakMinutes:r.break_minutes??0};return;}if(props.type==='BUSINESS_TRIP'||props.type==='PERSONAL_TRIP'){draft.value={startedAt:toLocalInput(r.started_at||r.occurredAt),endedAt:toLocalInput(r.ended_at),startOdometer:r.start_odometer??'',endOdometer:r.end_odometer??'',toll:r.toll_paise!=null?Number(r.toll_paise)/100:'',parking:r.parking_paise!=null?Number(r.parking_paise)/100:''};return;}if(props.type==='REVENUE'){draft.value={date:r.business_date||localDate(r.occurredAt),amount:r.amount??(r.amount_paise!=null?Number(r.amount_paise)/100:''),description:r.description||''};return;}if(props.type==='EXPENSE'){draft.value={date:r.date||localDate(r.occurredAt),amount:r.amount??(r.amount_paise!=null?Number(r.amount_paise)/100:''),category:r.category||'',description:r.description||'',reference:r.reference||''};return;}draft.value={};}

async function reverseGeocode(position){const {latitude,longitude}=position.coords;try{const response=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(latitude)}&lon=${encodeURIComponent(longitude)}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Reverse geocode unavailable');const data=await response.json();const address=data.address||{};const name=data.display_name||[address.suburb,address.city_district,address.city,address.town,address.village].filter(Boolean).join(', ')||null;draft.value.locationName=name;const areaText=String(name||'').toLowerCase();draft.value.locationArea=areaText.includes('navi mumbai')?'MUMBAI':areaText.includes('mumbai')?'MUMBAI':name?'OUTSIDE':'UNKNOWN';gpsStatus.value=name?`GPS: ${name}`:`GPS: ${latitude.toFixed(5)}, ${longitude.toFixed(5)}`;}catch{gpsStatus.value=`GPS: ${latitude.toFixed(5)}, ${longitude.toFixed(5)}`;}}
function onPosition(position){lastPosition=position;gpsStatus.value=`GPS captured · ${position.coords.latitude.toFixed(5)}, ${position.coords.longitude.toFixed(5)}`;clearTimeout(reverseTimer);reverseTimer=setTimeout(()=>{void reverseGeocode(position);},100);}
function startGps(){if(!navigator.geolocation){gpsStatus.value='GPS unavailable on this device/browser';return;}gpsStatus.value='Requesting GPS…';watchId=navigator.geolocation.watchPosition(onPosition,()=>{gpsStatus.value='GPS permission unavailable';},{enableHighAccuracy:true,maximumAge:30000,timeout:10000});navigator.geolocation.getCurrentPosition(onPosition,()=>{}, {enableHighAccuracy:true,maximumAge:0,timeout:10000});}
function stopGps(){if(watchId!==null&&navigator.geolocation)navigator.geolocation.clearWatch(watchId);watchId=null;clearTimeout(reverseTimer);}
function validate(){if(props.type==='FUEL'){const odometer=Number(draft.value.odometer),price=Number(draft.value.pricePerKg),amount=Number(draft.value.amount);if(!Number.isInteger(odometer)||odometer<0)return 'Enter a valid odometer.';if(props.mode==='CREATE'&&authoritative.value!=null&&odometer<authoritative.value)return 'Fuel odometer cannot be below the current authoritative odometer.';if(!Number.isFinite(price)||price<=0)return 'Enter a valid price per kg.';if(!Number.isFinite(amount)||amount<=0)return 'Enter a valid amount.';return '';}if(props.type==='REVENUE'||props.type==='EXPENSE'){if(!draft.value.date)return 'Date is required.';if(!(Number(draft.value.amount)>0))return 'Amount must be positive.';}return '';}
async function save(){if(busy.value)return;error.value='';const validation=validate();if(validation){error.value=validation;return;}busy.value=true;try{let saved;if(props.mode==='EDIT'){const event={entityType:title.value,entityId:props.record?.entityId||props.record?.id};let changes={};if(props.type==='FUEL')changes={recordedAt:fromLocalInput(draft.value.recordedAt),odometer:Number(draft.value.odometer),pricePerKg:Number(draft.value.pricePerKg),amount:Number(draft.value.amount),locationName:draft.value.locationName,locationArea:draft.value.locationArea};else if(props.type==='WORK_SESSION')changes={startedAt:fromLocalInput(draft.value.startedAt),endedAt:fromLocalInput(draft.value.endedAt),startOdometer:draft.value.startOdometer,endOdometer:draft.value.endOdometer,breakMinutes:draft.value.breakMinutes};else if(props.type==='BUSINESS_TRIP'||props.type==='PERSONAL_TRIP')changes={startedAt:fromLocalInput(draft.value.startedAt),endedAt:fromLocalInput(draft.value.endedAt),startOdometer:draft.value.startOdometer,endOdometer:draft.value.endOdometer,toll:draft.value.toll,parking:draft.value.parking};else if(props.type==='REVENUE')changes={date:draft.value.date,amount:Number(draft.value.amount),description:draft.value.description};else if(props.type==='EXPENSE')changes={date:draft.value.date,amount:Number(draft.value.amount),category:draft.value.category,description:draft.value.description,reference:draft.value.reference};saved=await application.saveHistoricalCorrection(event,changes);}else if(props.type==='FUEL'){const now=fromLocalInput(draft.value.recordedAt)||new Date().toISOString();const p=lastPosition; saved=await application.recordFuel({odometer:Number(draft.value.odometer),price_per_kg:Number(draft.value.pricePerKg),amount_paise:Math.round(Number(draft.value.amount)*100),recorded_at:now,date:now.slice(0,10),scope:'BUSINESS',entry_source:'FUEL',latitude:p?.coords?.latitude??null,longitude:p?.coords?.longitude??null,location_name:draft.value.locationName||null,location_area:draft.value.locationArea||null});}else if(props.type==='REVENUE')saved=await application.recordRevenue({amount_paise:Math.round(Number(draft.value.amount)*100),business_date:draft.value.date,recorded_at:new Date().toISOString(),scope:'BUSINESS',description:draft.value.description||''});else if(props.type==='EXPENSE')saved=await application.recordExpense(draft.value);else if(props.type==='WORK_SESSION')saved=await application.startWork({started_at:fromLocalInput(draft.value.startedAt),start_odometer:Number(draft.value.startOdometer)});else if(props.type==='BUSINESS_TRIP'||props.type==='PERSONAL_TRIP')saved=await application.recordTrip({scope:props.type==='PERSONAL_TRIP'?'PERSONAL':'BUSINESS',trip_type:props.type==='PERSONAL_TRIP'?'PERSONAL':'BUSINESS',status:'COMPLETED',started_at:fromLocalInput(draft.value.startedAt),ended_at:fromLocalInput(draft.value.endedAt),start_odometer:Number(draft.value.startOdometer)||null,end_odometer:Number(draft.value.endOdometer)||null,toll_paise:Math.round(Number(draft.value.toll||0)*100),parking_paise:Math.round(Number(draft.value.parking||0)*100)});else throw new Error('This record type does not have an independent create operation.');success.value=props.mode==='EDIT'?'Historical record updated successfully.':'Fuel record saved successfully.';emit('saved',saved);setTimeout(()=>emit('close'),1400);}catch(e){error.value=String(e?.message||e);}finally{busy.value=false;}}
function cancel(){if(!busy.value)emit('close');}
watch(()=>[props.type,props.mode,props.record,props.authoritativeOdometer],setDraftFromRecord,{immediate:true});
onMounted(()=>{if(isFuel.value)startGps();});onUnmounted(stopGps);
</script>
<template>
<div class="kfe-authoritative-overlay" role="dialog" aria-modal="true" :aria-label="`${mode} ${title}`">
 <form class="kfe-authoritative-card" @submit.prevent="save">
  <header><div><p class="kfe-eyebrow">{{mode}} · {{title}}</p><h2>{{mode==='EDIT'?'Correct':'Record'}} {{title}}</h2></div><button type="button" class="kfe-form-close" :disabled="busy" @click="cancel">×</button></header>
  <template v-if="type==='FUEL'">
   <p class="kfe-form-help">Authoritative CNG refuel record. Timestamp and location are captured automatically.</p>
   <label class="kfe-auth-field black-odometer">Odometer *<input v-model="draft.odometer" inputmode="numeric" type="number" min="0" step="1" required></label>
   <label class="kfe-auth-field">Price per kg *<input v-model="draft.pricePerKg" inputmode="decimal" type="number" min="0" step="0.01" required></label>
   <label class="kfe-auth-field">Amount *<input v-model="draft.amount" inputmode="decimal" type="number" min="0" step="0.01" required></label>
   <div class="kfe-auth-calculated"><span>Refuelled fuel</span><strong>{{quantityKg==null?'—':quantityKg.toFixed(3)+' kg'}}</strong></div>
   <div class="kfe-auth-meta"><span>🕒 {{timestampLabel}}</span><span>📍 {{locationLabel}}</span><small>{{gpsStatus}}</small></div>
  </template>
  <template v-else-if="type==='WORK_SESSION'">
   <label class="kfe-auth-field">Start time<input v-model="draft.startedAt" type="datetime-local" required></label><label class="kfe-auth-field">End time<input v-model="draft.endedAt" type="datetime-local"></label><label class="kfe-auth-field">Start odometer<input v-model="draft.startOdometer" type="number" min="0"></label><label class="kfe-auth-field">End odometer<input v-model="draft.endOdometer" type="number" min="0"></label><label class="kfe-auth-field">Break minutes<input v-model="draft.breakMinutes" type="number" min="0" step="1"></label>
  </template>
  <template v-else-if="type==='BUSINESS_TRIP'||type==='PERSONAL_TRIP'">
   <label class="kfe-auth-field">Start time<input v-model="draft.startedAt" type="datetime-local" required></label><label class="kfe-auth-field">End time<input v-model="draft.endedAt" type="datetime-local"></label><label class="kfe-auth-field">Start odometer<input v-model="draft.startOdometer" type="number" min="0"></label><label class="kfe-auth-field">End odometer<input v-model="draft.endOdometer" type="number" min="0"></label><label class="kfe-auth-field">Toll<input v-model="draft.toll" type="number" min="0" step="0.01"></label><label class="kfe-auth-field">Parking<input v-model="draft.parking" type="number" min="0" step="0.01"></label>
  </template>
  <template v-else-if="type==='REVENUE'||type==='EXPENSE'">
   <label class="kfe-auth-field">Date<input v-model="draft.date" type="date" required></label><label class="kfe-auth-field">Amount<input v-model="draft.amount" type="number" min="0" step="0.01" required></label><label v-if="type==='EXPENSE'" class="kfe-auth-field">Category<input v-model="draft.category" type="text"></label><label class="kfe-auth-field">Description<input v-model="draft.description" type="text"></label><label v-if="type==='EXPENSE'" class="kfe-auth-field">Receipt / reference<input v-model="draft.reference" type="text"></label>
  </template>
  <p v-if="error" class="kfe-auth-error" role="alert">{{error}}</p><p v-if="success" class="kfe-auth-success" role="status">✓ {{success}}</p>
  <div class="kfe-auth-actions"><button type="button" class="secondary-action" :disabled="busy" @click="cancel">Cancel</button><button type="submit" class="primary-action" :disabled="busy">{{busy?'Saving…':mode==='EDIT'?'Save correction':'Save'}}</button></div>
 </form>
</div>
</template>
<style scoped>
.kfe-authoritative-overlay{position:fixed;inset:0;z-index:1100;display:grid;place-items:center;padding:1rem;background:rgba(0,0,0,.5)}.kfe-authoritative-card{width:min(34rem,100%);max-height:92vh;overflow:auto;padding:1.25rem;border-radius:18px;background:var(--kfe-shell-surface,#fff);color:var(--kfe-shell-text,#111);box-shadow:0 20px 60px rgba(0,0,0,.25)}.kfe-authoritative-card header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.kfe-authoritative-card h2{margin:.2rem 0 1rem}.kfe-form-close{border:0;background:transparent;font-size:1.8rem;line-height:1;cursor:pointer}.kfe-form-help{font-size:.86rem;opacity:.78}.kfe-auth-field{display:grid;gap:.35rem;margin:.8rem 0;font-weight:700}.kfe-auth-field input{width:100%;box-sizing:border-box;padding:.78rem;border:1px solid #c7cbd1;border-radius:10px;background:#fff;color:#111}.black-odometer input{background:#111;color:#fff;border-color:#111}.kfe-auth-calculated,.kfe-auth-meta{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:.8rem 0;border-top:1px solid #e3e5e8}.kfe-auth-meta{flex-wrap:wrap;font-size:.8rem}.kfe-auth-meta small{width:100%;opacity:.72}.kfe-auth-error{padding:.7rem;border-radius:10px;background:#ffe9e9;color:#8a1f1f}.kfe-auth-success{padding:.8rem;border-radius:10px;background:#e9f8ed;color:#176b32;font-weight:800}.kfe-auth-actions{display:flex;justify-content:flex-end;gap:.6rem;margin-top:1rem}.secondary-action,.primary-action{padding:.72rem 1rem;border-radius:10px;border:1px solid #bbb;background:#fff;cursor:pointer}.primary-action{font-weight:800}.secondary-action:disabled,.primary-action:disabled{opacity:.55;cursor:wait}
</style>